using System.Linq;
using CavesOfOoo.Core;
using CavesOfOoo.Rendering;
using NUnit.Framework;
using UnityEngine;
namespace CavesOfOoo.Tests
{
 public sealed class FlatPixelMorrowfastRiverTests
 {
  const string Art="Sprites/Live16x24/felling-blackwater";
  DensityLootTestScope content;OverworldZoneManager manager;Zone zone;FlatPixelGreyboxCatalog world;Entity water;int x,y;
  [SetUp] public void Setup(){content=new DensityLootTestScope();manager=OverworldZoneManager.CreateDetached(content.Factory,64,true);zone=manager.GetZone(MorrowfastSceneRuntime.ZoneID);manager.SetActiveZone(zone);foreach(var c in zone.Cells)c.Explored=c.IsVisible=true;var cell=zone.Cells.Cast<Cell>().First(c=>c.Objects.Count==1&&c.Objects[0].BlueprintName=="WaterPuddle");x=cell.X;y=cell.Y;water=cell.Objects[0];world=new FlatPixelGreyboxCatalog();}
  [TearDown] public void Cleanup(){world?.Dispose();content?.Dispose();}
  FlatPixelGreyboxCell View(){Assert.True(world.TryResolvePresentation(zone,x,y,out var v));return v;}
  bool Native(){var v=View();return v.LocalGround&&v.GroundTile.sprite.texture==Resources.Load<Texture2D>(Art);}
  void Reader(bool native){bool found=world.TryGetPresentationSubjectSprite(zone,water,x,y,out var s,out _);if(native)Assert.True(found);if(found)Assert.AreEqual(native,s.texture==Resources.Load<Texture2D>(Art));}
  [Test] public void All67AuthoredWaterCellsKeepAuthoredBlockingMeaning(){int count=0,version=zone.EntityVersion;string state=zone.TileState.ToSaveString();foreach(var spec in MorrowfastSceneDefinition.Load().cells.Where(c=>c.water)){x=spec.x;y=spec.y;Assert.True(Native(),x+","+y);Assert.AreEqual(spec.solid,View().BlocksMovement);Assert.False(zone.GetCell(x,y).IsWall());count++;}Assert.AreEqual(67,count);Assert.AreEqual(version,zone.EntityVersion);Assert.AreEqual(state,zone.TileState.ToSaveString());}
  [Test] public void WaterReaderAndCoveredBodyShareSubstrateIdentity(){Assert.True(Native());Reader(true);var player=content.Factory.CreateEntity("Player");Assert.True(zone.AddEntity(player,x,y));Assert.True(Native());Assert.AreSame(player,View().Owner);Reader(true);Assert.True(zone.RemoveEntity(water));Assert.False(Native());}
  [TestCase("id")][TestCase("tag")][TestCase("solid")][TestCase("solid-tag")][TestCase("wall")][TestCase("layer")][TestCase("color")][TestCase("glyph")][TestCase("hidden")][TestCase("memory")][TestCase("unexplored")][TestCase("volume")][TestCase("liquid")][TestCase("oil")][TestCase("heat")][TestCase("revision")][TestCase("poi")][TestCase("graph")][TestCase("foreign-part")][TestCase("duplicate")][TestCase("frozen")][TestCase("boiling")][TestCase("nonfinite")][TestCase("cold")][TestCase("charge")][TestCase("residue")][TestCase("lower-vapor")][TestCase("nan-vapor")]
  public void ChangedMeaningOrDisclosureRevokesWarmNativeWater(string change){Assert.True(Native());switch(change){
   case "id":water.ID="foreign";break;case "tag":water.Tags.Remove(MorrowfastSceneRuntime.TerrainTag);break;
   case "solid":water.GetPart<PhysicsPart>().Solid=false;break;case "solid-tag":water.Tags.Remove("Solid");break;case "wall":water.SetTag("Wall");break;
   case "layer":water.GetPart<RenderPart>().RenderLayer=2;break;case "color":water.GetPart<RenderPart>().ColorString="&R";break;case "glyph":water.GetPart<RenderPart>().RenderString="!";break;
   case "hidden":water.GetPart<RenderPart>().Visible=false;break;case "memory":zone.GetCell(x,y).IsVisible=false;break;case "unexplored":zone.GetCell(x,y).Explored=false;break;
   case "volume":water.GetPart<LiquidPoolPart>().Volume=0;break;case "liquid":water.GetPart<LiquidPoolPart>().LiquidId="oil";break;case "oil":zone.TileState.WriteCoating(x,y,"oil",5);break;case "heat":zone.TileState.Get(x,y).Heat=1;break;
   case "lower-vapor":water.GetPart<ThermalPart>().VaporTemperature=10;break;case "nan-vapor":water.GetPart<ThermalPart>().VaporTemperature=float.NaN;break;case "frozen":water.GetPart<ThermalPart>().Temperature=0;break;case "boiling":water.GetPart<ThermalPart>().Temperature=100;break;case "nonfinite":water.GetPart<ThermalPart>().Temperature=float.NaN;break;case "cold":zone.TileState.Get(x,y).Cold=1;break;case "charge":zone.TileState.Get(x,y).Charge=1;break;case "residue":zone.TileState.Get(x,y).Residues.Add(new ZoneTileState.Layer{Id="soot",Turns=5});break;
   case "revision":MorrowfastSceneRuntime.GetState(zone).Revision=99;break;case "poi":manager.WorldMap.SetPOI(3,6,new PointOfInterest(POIType.MerchantCamp,"foreign"));break;case "graph":manager.CachedZones[zone.ZoneID]=new Zone(zone.ZoneID);break;
   case "foreign-part":water.AddPart(new CultivatedSoilPart());break;case "duplicate":Assert.True(zone.AddEntity(content.Factory.CreateEntity("WaterPuddle"),x,y));break;
  }if(world.TryResolvePresentation(zone,x,y,out var v))Assert.False(v.LocalGround&&v.GroundTile.sprite.texture==Resources.Load<Texture2D>(Art),change);if(world.TryGetPresentationSubjectSprite(zone,water,x,y,out var s,out _))Assert.AreNotSame(Resources.Load<Texture2D>(Art),s.texture,change);}
  [Test] public void CoveredReaderLosesHiddenMemoryThenRecovers(){Assert.True(Native());Assert.True(zone.AddEntity(content.Factory.CreateEntity("Player"),x,y));Reader(true);water.GetPart<RenderPart>().Visible=false;Reader(false);water.GetPart<RenderPart>().Visible=true;zone.GetCell(x,y).IsVisible=false;Reader(false);zone.GetCell(x,y).IsVisible=true;Reader(true);}
  [Test] public void MissingOptionalResourceRetainsFallback(){using(var missing=new FlatPixelGreyboxCatalog((Texture2D)null)){Assert.True(missing.TryResolvePresentation(zone,x,y,out var v));Assert.False(v.LocalGround);}}
  [Test] public void DisclosedNeighborJoinRevokesForHiddenAndCoveredWater(){x=22;y=21;water=zone.GetCell(x,y).Objects.First(o=>o.BlueprintName=="WaterPuddle");Assert.True(Native());var joined=View().GroundTile.sprite.rect;var east=zone.GetCell(x+1,y);east.IsVisible=false;var hidden=View().GroundTile.sprite.rect;Assert.AreNotEqual(joined,hidden);east.IsVisible=true;Assert.AreEqual(joined,View().GroundTile.sprite.rect);var actor=content.Factory.CreateEntity("Player");Assert.True(zone.AddEntity(actor,x+1,y));Assert.AreEqual(hidden,View().GroundTile.sprite.rect);Assert.True(zone.RemoveEntity(actor));Assert.AreEqual(joined,View().GroundTile.sprite.rect);}
  [Test] public void AdjacentVisibleFootprintPoolRevokesButHiddenDoesNot(){x=22;y=21;water=zone.GetCell(x,y).Objects.First(o=>o.BlueprintName=="WaterPuddle");Assert.True(Native());var other=content.Factory.CreateEntity("WaterPuddle");other.AddPart(new SpatialFootprintPart{CellsRaw="0,0;1,0"});var left=zone.GetCell(x-1,y).Objects.First(o=>o.BlueprintName=="WaterPuddle");foreach(var e in new[]{water,left}){e.GetPart<PhysicsPart>().Solid=false;e.Tags.Remove("Solid");}Assert.True(zone.AddEntity(other,x-1,y),"test footprint placement");foreach(var e in new[]{water,left}){e.GetPart<PhysicsPart>().Solid=true;e.SetTag("Solid");}Assert.False(Native(),"visible overlapping water must veto");Reader(false);other.GetPart<RenderPart>().Visible=false;Assert.True(Native());Reader(true);Assert.True(zone.RemoveEntity(other));Assert.True(Native());}
  [Test] public void SavedLairClaimStillRevokesRestoredSettlementLabel(){Assert.True(Native());var old=manager.WorldMap.GetPOI(3,6);manager.WorldMap.SetPOI(3,6,new PointOfInterest(POIType.Lair,"saved legacy",null,1,"DesertProwler"));LairStacks.Restore(manager,null);manager.WorldMap.SetPOI(3,6,old);Assert.False(Native());Reader(false);}
  [Test] public void AtlasHasNativePointImportAndStableIdentity(){var tex=Resources.Load<Texture2D>(Art);Assert.NotNull(tex);Assert.AreEqual(272,tex.width);Assert.AreEqual(24,tex.height);Assert.AreEqual(FilterMode.Point,tex.filterMode);Assert.True(Native());var sprite=View().GroundTile.sprite;Assert.AreSame(sprite,View().GroundTile.sprite);world.Dispose();Assert.NotNull(tex);}
  [Test] public void SixBridgeSupportCellsHaveBoardsAndKeepWaterUnderActors(){int n=0;foreach(var p in MorrowfastSceneDefinition.Load().FindOwner("western-footbridge").bridgeSupport){x=p.x;y=p.y;Assert.True(Native());Assert.False(View().BlocksMovement);Assert.NotNull(View().GroundDecorationTile);Assert.AreSame(Resources.Load<Texture2D>(FlatPixelSoddenTravelCatalog.ResourcePath),View().GroundDecorationTile.sprite.texture);var actor=content.Factory.CreateEntity("Player");Assert.True(zone.AddEntity(actor,x,y));Assert.AreSame(actor,View().Owner);Assert.NotNull(View().GroundDecorationTile);zone.RemoveEntity(actor);n++;}Assert.AreEqual(6,n);}
  [TestCase("removed")][TestCase("moved")][TestCase("hidden")][TestCase("memory")][TestCase("component")]
  public void ChangedBridgeWithdrawsAllSupportArt(string change){var bridge=MorrowfastSceneRuntime.FindOwner(zone,"western-footbridge");x=23;y=13;Assert.NotNull(View().GroundDecorationTile);switch(change){case "removed":zone.RemoveEntity(bridge);break;case "moved":zone.RemoveEntity(bridge);zone.AddEntity(bridge,24,15);break;case "hidden":bridge.GetPart<RenderPart>().Visible=false;break;case "memory":zone.GetCell(24,14).IsVisible=false;break;case "component":bridge.GetPart<MorrowfastPropPart>().ComponentId="foreign";break;}Assert.Null(View().GroundDecorationTile);Assert.True(Native());}

  [TestCase(false,true)][TestCase(true,false)][TestCase(false,false)][TestCase(true,true)]
  public void OptionalRiverAndBoardsAreIndependent(bool river,bool boards){using(var selector=new FlatPixelFallbackCatalog())using(var a=new FlatPixelMorrowfastRiverCatalog(river?Resources.Load<Texture2D>(Art):null,boards?Resources.Load<Texture2D>(FlatPixelSoddenTravelCatalog.ResourcePath):null,selector)){Assert.AreEqual(river,a.TryResolveWater(zone,23,13,out _,out _));Assert.AreEqual(boards,a.Bridge(zone,23,13)!=null);a.Dispose();Assert.False(a.TryResolveWater(zone,23,13,out _,out _));Assert.Null(a.Bridge(zone,23,13));}Assert.NotNull(Resources.Load<Texture2D>(Art));}
  [Test] public void MalformedOptionalAtlasesDoNotEscapeFallback(){var malformed=new Texture2D(271,24);try{using(var selector=new FlatPixelFallbackCatalog())using(var a=new FlatPixelMorrowfastRiverCatalog(malformed,malformed,selector)){Assert.False(a.TryResolveWater(zone,x,y,out _,out _));Assert.Null(a.Bridge(zone,23,13));}}finally{Object.DestroyImmediate(malformed);}}
  [Test] public void ForeignStatePartOwnershipRefusesScene(){Assert.True(Native());var state=MorrowfastSceneRuntime.GetState(zone);state.ParentEntity=content.Factory.CreateEntity("TepuiStone");Assert.False(Native());}
  [Test] public void BridgeRemovalWithdrawsVisualSupportAndPreservesRuntimeBlock(){x=23;y=13;Assert.NotNull(View().GroundDecorationTile);Assert.False(zone.GetCell(x,y).BlocksMovement());var bridge=MorrowfastSceneRuntime.FindOwner(zone,"western-footbridge");Assert.True(zone.RemoveEntity(bridge));Assert.Null(View().GroundDecorationTile);Assert.True(zone.GetCell(x,y).BlocksMovement());Assert.True(Native());}

  [TestCase("custody")][TestCase("foreign-render")][TestCase("foreign-physics")][TestCase("zero-stack")]
  public void InvalidPhysicalCompetitorDoesNotRevokeRiver(string change){Assert.True(Native());var other=content.Factory.CreateEntity("WaterPuddle");Assert.True(zone.AddEntity(other,x,y));Assert.False(Native());var foreign=content.Factory.CreateEntity("Player");switch(change){case "custody":other.GetPart<PhysicsPart>().InInventory=foreign;break;case "foreign-render":other.GetPart<RenderPart>().ParentEntity=foreign;break;case "foreign-physics":other.GetPart<PhysicsPart>().ParentEntity=foreign;break;case "zero-stack":other.AddPart(new StackerPart{StackCount=0});break;}Assert.True(Native());Reader(true);}
  [Test] public void DisposalKeepsBothBorrowedTexturesAlive(){var river=Resources.Load<Texture2D>(Art);var boards=Resources.Load<Texture2D>(FlatPixelSoddenTravelCatalog.ResourcePath);using(var selector=new FlatPixelFallbackCatalog()){var a=new FlatPixelMorrowfastRiverCatalog(river,boards,selector);Assert.True(a.TryResolveWater(zone,x,y,out var tile,out _));Assert.NotNull(a.Bridge(zone,23,13));a.Dispose();Assert.True(river!=null);Assert.True(boards!=null);Assert.True(tile==null);} }

 }
}
